/** Round axis ticks (1/2/5×10^k steps) that are multiples of the step, so zero is a tick when in range. */
export function niceTicks(min: number, max: number): number[] {
	if (!Number.isFinite(min) || !Number.isFinite(max)) return [0];
	if (min === max) return [0, min === 0 ? 0 : min].filter((v, i, a) => a.indexOf(v) === i);
	const lo = Math.min(min, max);
	const hi = Math.max(min, max);
	const raw = (hi - lo) / 4;
	const mag = 10 ** Math.floor(Math.log10(raw));
	const norm = raw / mag;
	const step = mag * (norm < 1.5 ? 1 : norm < 3.5 ? 2 : norm < 7.5 ? 5 : 10);
	const out: number[] = [];
	for (let v = Math.ceil(lo / step) * step; v <= hi; v += step) out.push(Math.round(v / step) * step);
	return out.length ? out : [0];
}

/** UTC date label with dot separators, e.g. 2022.01.01 (never a trailing -01 January tick). */
export function dateLabel(ts: number): string {
	const d = new Date(ts);
	const p = (n: number) => String(n).padStart(2, "0");
	return `${d.getUTCFullYear()}.${p(d.getUTCMonth() + 1)}.${p(d.getUTCDate())}`;
}

/** Trial for a horizon, falling back to the lead trial when the feature lacks that horizon. */
export function trialAt(f: ScreenFeature, h: "lead" | number): ScreenTrial {
	if (h === "lead") return leadTrial(f);
	return f.trials.find((t) => t.h === h) ?? leadTrial(f);
}

/** Percent curve view: fraction sums ×100, a missing point carries over the previous value (0 first). */
export function curveView(trial: ScreenTrial | undefined | null) {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const pct = (xs: (number | null)[]) => {
		let prev = 0;
		return xs.map((x) => {
			if (x != null && Number.isFinite(x)) prev = x;
			return prev * 100;
		});
	};
	const rule = pct(curve.rule ?? []);
	const hold = pct(curve.hold ?? []);
	const values = [...rule, ...hold];
	return {
		t: curve.t,
		rule,
		hold,
		ticks: niceTicks(Math.min(...values), Math.max(...values)),
		labels: curve.t.map(dateLabel),
	};
}

